# Generated by Claude (Claude Code).
"""Chart of a PeakCount training log: loss and accuracy per epoch in one chart.

Used by train.py after training; not meant to be run on its own.
"""

import csv
import math
from pathlib import Path

from matplotlib.figure import Figure
from matplotlib.ticker import MaxNLocator, PercentFormatter

SURFACE = "#fcfcfb"
TEXT_PRIMARY = "#0b0b0b"
TEXT_SECONDARY = "#52514e"
TEXT_MUTED = "#898781"
GRIDLINE = "#e1e0d9"
AXIS = "#c3c2b7"
LOSS_COLOR = "#2a78d6"      # categorical slot 1 (blue)
ACCURACY_COLOR = "#eb6834"  # categorical slot 2 (orange)

RC = {
    "font.family": ["Segoe UI", "DejaVu Sans"],
    "font.size": 10,
}


def nice_axis_top(value: float) -> float:
    """Smallest 'nice' top (1, 1.25, 2.5, 5 x 10^k) >= value, so that top / 5 is a clean tick step."""
    scale = 10.0 ** math.floor(math.log10(value))
    for factor in (1.0, 1.25, 2.5, 5.0, 10.0):
        if factor * scale >= value:
            return factor * scale
    return 10.0 * scale


def plot_training_log(csv_path: Path) -> Path:
    """Draw the training log at csv_path and save it as a PNG next to it; return the PNG path."""
    csv_path = Path(csv_path)
    with open(csv_path, newline="") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        raise ValueError(f"{csv_path} contains no epochs")

    epochs = [int(r["epoch"]) for r in rows]
    loss = [float(r["loss"]) for r in rows]
    accuracy = [100 * float(r["accuracy"]) for r in rows]
    marker = "o" if len(rows) == 1 else None

    from matplotlib import rc_context

    with rc_context(RC):
        fig = Figure(figsize=(8, 4.8), dpi=150, facecolor=SURFACE)
        ax_loss = fig.add_subplot()
        ax_acc = ax_loss.twinx()
        ax_loss.set_facecolor(SURFACE)

        (loss_line,) = ax_loss.plot(epochs, loss, color=LOSS_COLOR, linewidth=2,
                                    solid_capstyle="round", solid_joinstyle="round",
                                    marker=marker, label="Loss (left axis)")
        (acc_line,) = ax_acc.plot(epochs, accuracy, color=ACCURACY_COLOR, linewidth=2,
                                  solid_capstyle="round", solid_joinstyle="round",
                                  marker=marker, label="Accuracy (right axis)")

        ax_loss.set_xlim(epochs[0] - 0.5 if len(epochs) == 1 else epochs[0],
                         epochs[-1] + 0.5 if len(epochs) == 1 else epochs[-1])
        ax_loss.xaxis.set_major_locator(MaxNLocator(integer=True))
        # Both axes get 5 equal intervals, so the accuracy ticks sit on the loss gridlines.
        loss_top = nice_axis_top(max(loss) * 1.02)
        ax_loss.set_ylim(0, loss_top)
        ax_loss.set_yticks([loss_top * i / 5 for i in range(6)])
        ax_acc.set_ylim(0, 100)
        ax_acc.set_yticks(range(0, 101, 20))
        ax_acc.yaxis.set_major_formatter(PercentFormatter(decimals=0))

        ax_loss.set_xlabel("Epoch", color=TEXT_SECONDARY)
        ax_loss.set_ylabel("Loss (cross-entropy)", color=TEXT_SECONDARY)
        ax_acc.set_ylabel("Accuracy", color=TEXT_SECONDARY)

        # Gridlines from the loss axis only, so the two scales don't draw two grids.
        ax_loss.grid(axis="y", color=GRIDLINE, linewidth=1)
        ax_loss.set_axisbelow(True)

        for ax in (ax_loss, ax_acc):
            ax.spines["top"].set_visible(False)
            for side in ("left", "right", "bottom"):
                ax.spines[side].set_color(AXIS)
                ax.spines[side].set_linewidth(1)
            ax.tick_params(colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=6)

        fig.suptitle("PeakCNN training", x=0.08, y=0.97, ha="left",
                     fontsize=13, fontweight="semibold", color=TEXT_PRIMARY)
        fig.text(0.08, 0.905,
                 f"{csv_path.name}  ·  after epoch {epochs[-1]}: "
                 f"loss {loss[-1]:.4f}, accuracy {accuracy[-1]:.2f}%",
                 ha="left", fontsize=9, color=TEXT_SECONDARY)
        legend = ax_loss.legend(handles=[loss_line, acc_line], loc="lower left",
                                bbox_to_anchor=(0, 1.01), ncol=2, frameon=False,
                                borderaxespad=0, handlelength=1.6)
        for text in legend.get_texts():
            text.set_color(TEXT_SECONDARY)

        fig.subplots_adjust(left=0.08, right=0.91, top=0.8, bottom=0.12)
        png_path = csv_path.with_suffix(".png")
        fig.savefig(png_path, facecolor=SURFACE)
    return png_path
